"""Encode semantic decisions made after reading every indexed note and its source passage.
No classification is inferred from headings, keywords, or note summaries by this program.
Line numbers are 1-based in the unchanged combined transcription.
"""
from pathlib import Path
import json,csv,datetime,hashlib
W=Path(__file__).resolve().parents[1]
PKG='MPL_138_001-045'; TF=PKG+'_transcription.tex'
items=[];entries=[];events=[]
def add(ns,kind,loc,words,statement,reconstruction,check,reason,corrections=None):
    ident='SA09-'+str(104+min(ns)); sources=[PKG+'#'+str(n) for n in ns]
    items.append(dict(id=ident,sources=sources,kind=kind,cote=138,scans=sorted(set(x[0] for x in loc)),lines=[TF+':'+str(x[1])+'-'+str(x[2]) for x in loc],his_words=words,statement=statement,reconstruction=reconstruction,check=check,check_reason=reason))
    corrections=corrections or {}
    for j,n in enumerate(ns):
        verdict,extra=corrections.get(n,('kept' if j==0 else 'merged into item '+ident,''))
        entries.append(dict(entry_id=PKG+'#'+str(n),item_id=ident,verdict=verdict,reason=reason+(' '+extra if extra else '')))
    events.append(dict(statement_id=ident,date='2026-11-19',who='GPT-6 Astra Pro; inherited effort (not separately exposed); SA09/cote138_early',type='used and rechecked in this run',outcome='Source comparison: '+check+'. '+reason+' This event certifies the textual comparison; it is not by itself a proof of the mathematical assertion.'))
add([1],'other',[(5,141,187),(29,963,971),(37,1362,1372)],'«l’étude arithmétique des rev. étales abéliens»','The packet moves from descent of schemes and covering pairs to the maximal geometric abelian étale tower over U=P¹−{0,1,∞}, then to chosen fibres and cartography. The asserted geometric quotient is π₁(U)ab≅T³/T, T=lim μ_n.','This is an organizational synthesis. The project comparisons in the note are earlier-run leads, not manuscript conclusions.','agrees','The descent formulas and the explicit abelian qualifier occur at the cited passages; no arbitrary-cover or full-Galois-image theorem is inferred.')
add([2,75],'title, date or page count',[(2,20,24),(3,90,120)],'«Abonnement à Topologie structurale pour 1980 (N°s 4-6)»','The inserted communiqué advertises issue 4; the order form offers a 1980 subscription and issues 1–3 from 1979. These dates date the printed objects only.','No date of mathematical composition or insertion is reconstructed.','agrees','The printed dates and issue counts are explicit. They cannot date separate handwritten leaves or supply their page count.')
add([3,78],'title, date or page count',[(43,1632,1662),(45,1757,1784)],'«15 Juin 1978»; «22 Juin 1978»','Two administrative leaves are dated 15 and 22 June 1978; the former announces a thesis defense for 5 July 1978, the latter is cancelled and contains 1978/1979 deadlines.','No recto–verso pairing or global terminus post quem for the mathematics is inferred.','agrees','The notices contain the cited dates and the thesis title; scan order alone does not establish which handwritten page reused which physical sheet.')
add([4,8],'reading question',[(4,132,137),(18,508,521),(3,90,120),(43,1632,1649)],'«dictionnaire galoisien» [all title words uncertain]; «Tour des rev. de Fermat»','The supplied mathematical leaves lack a secure authorial date; neither priority over other archival folders nor priority over Belyi’s theorem follows from the supplied insert dates.','Catalogue and Esquisse chronology must be distinguished from dating these leaves. Belyi publication/receipt history is public-source evidence, not manuscript evidence.','agrees','The notes correctly limit the chronological inference. Their catalogue and Esquisse citations require independent verification and do not resolve the handwriting date.')
add([5],'unpursued implication',[(25,789,830),(37,1362,1372),(44,1693,1703)],'«cartes 3-pondérées finies abéliennes»','For n≥1 over Q, C_n:x^n+y^n+z^n=0 maps to C_1 by coordinate n-th powers and is a μ_n³/μ_n torsor after removing the three coordinate-zero fibres. This displayed rational family supplies finite triangular maps; n=2 is the octahedral example.','Identifying the lifted interval with a dessin is a modern explanation of the given family. No arbitrary-curve existence assertion is added.','agrees','The equations, branch set and abelian cartographic programme are explicit; the external cote-144 comparison is only a lead.')
add([6],'reading question',[(15,424,471),(29,963,971),(37,1362,1372)],'«rev. étales abéliens»','No assertion quantifying over every smooth projective curve over Qbar and furnishing a three-branch-point map occurs in scans 1–45.','This is a bounded negative textual finding after reading the whole package. Belyi’s general criterion is a separate literature result.','agrees','The packet constructs the Fermat/Kummer family and announces a comparison; the claimed universal quantifier is absent here.')
add([7],'unpursued implication',[(28,917,959),(36,1334,1346),(37,1350,1360)],'«via le caractère fondamental»; «à travers»','The G_Q-action on M=T³/T is scalar through the cyclotomic character, and the displayed special-fibre action factors through the affine Kummer representation for 2. These data do not establish faithfulness of G_Q on all finite dessins or on π₁(U).','The nonfaithfulness of this restricted cyclotomic/Kummer quotient is a mathematical deduction; it is not a negative assertion about the full outer action.','agrees','The source names its quotients explicitly. The note correctly keeps a full arithmetic faithfulness assertion outside this packet.')
add([9],'other',[(5,139,187),(25,788,830),(44,1681,1703)],'«x^n+y^n+z^n=0»; «l’octaèdre»','The supplied transcription covers descent, Kummer theory, Fermat covers, and the octahedron. The earlier note reports that an external context digest incorrectly denied overlap with Hua’s account.','The external Hua file and RESULTS_STATE digest are not supplied; their mutual discrepancy is preserved as the earlier run’s report.','not on the page','The mathematical themes are on the pages, but the assertion about two external context files cannot be independently checked from this archive.',{9:('corrected','Restricted the verdict to manuscript overlap and attributed the uncheckable context-file comparison to the earlier run.')})
add([10],'unproved claim',[(5,155,187),(6,191,206)],'«Une donnée de descente … revient à un scindage»; «conditions d’effectivité»','Let k^s/k be a separable closure and X/k^s a connected scheme with the stated constant-field condition. A continuous semilinear descent datum is a section of Aut_k(X)→G_k over its full image when a section exists; an effective datum gives a k-model with a specified base-change isomorphism. Quasi-projectivity is a sufficient effectivity setting for continuous finite-type Galois descent.','Continuity, the topology of semilinear automorphisms, and finite-type descent are made explicit here; the manuscript only records the effectivity caveat.','agrees','The note correctly retains the effectivity qualification rather than asserting that every abstract group section is an effective descent.')
add([11,82],'withdrawn in the same text',[(5,155,170),(7,262,264),(8,277,300)],'«même image» [uncertain], replacing «surjectif»','The semilinear map need not surject onto G_k. For a covering-pair automorphism map E→G compatible with arithmetic projections, surjectivity is equivalent to surjectivity on geometric kernels and equality of arithmetic images.','Modern exact-diagram formulation. The revised image condition is read as written, with its uncertainty retained.','agrees','Scan 8 explicitly deletes surjectivity onto Γ and substitutes equality of images; this is a substantive correction, not a claim that descent always exists.')
add([12,80],'withdrawn in the same text',[(6,209,232),(7,239,264)],'«plus gén. un rev. profini galoisien» [deleted]; «Norm_E(N)»','For a connected geometric scheme and a universal profinite étale cover with deck group Π, automorphisms of the base lift to an extension by Π. A connected Galois cover defined by closed normal N⊂Π has pair-automorphism group N_E(N)/N; its image in base automorphisms is the stabilizer of N. Surjectivity holds exactly when N is E-invariant.','Pro-objects and continuity are explicit hypotheses; they are implicit in the manuscript’s universal profinite terminology.','agrees','The broad universal-cover sentence is deleted and replaced by a normalizer construction for a general Galois covering. Both places were read.')
add([13],'unproved claim',[(7,262,264)],'«syst. fond. de voisinages de 1 … stables par tt autom continu»','A topologically finitely generated profinite group Π has a cofinal basis of characteristic open normal subgroups: intersect all open subgroups of index at most m. There are finitely many because continuous homomorphisms to each finite symmetric group are determined by finitely many generators.','The word topological is reconstructed in the standard profinite sense; it is crossed out before the surviving type-fini phrase.','agrees','The source states the basis assertion without its finite-homomorphism argument. The note identifies the necessary proof correctly.')
add([14,98],'reading question',[(8,298,300),(10,353,355)],'«prés. finie sur k»','A scheme of finite presentation over k^s, together with a finite-presentation morphism or finitely many automorphisms, descends to a finite subextension of k^s/k. Consequently its arithmetic isomorphism stabilizer contains an open subgroup.','The required base is k^s, not generally k: a nonempty finite-type k-scheme cannot carry an infinite algebraic extension k^s as constants. The modern corrected statement is not an emendation.','agrees','The notes correctly identify the discrepancy between the written k and the kbar used by the finite-definition argument; both affected source passages retain the written symbols.')
add([15,81],'withdrawn in the same text',[(7,268,268),(8,272,296),(9,304,339)],'«Une donnée de descente sur (X′−X)/kbar … scindage»','Continuous descent data on a covering pair X′→X correspond to sections of its semilinear pair-automorphism map to G_k; restriction to an intermediate field gives partial sections. Forgetting the cover composes with the automorphism map of the base. Effectivity remains a separate requirement.','The morphism is part of the descended object; topology/effectivity are restored explicitly.','agrees','The cancelled initial §2.3 is restarted by defining the geometric kernel, and §2.4 then restates descent. The descent principle itself is not withdrawn.')
add([16],'unproved claim',[(10,344,355),(11,359,374)],'«un groupe quotient fini … par image inverse»','For a profinite extension 1→H→E→Γ→1 with H finite, choose an open normal V⊂E with V∩H=1. Then E≅(E/V)×_(Γ/p(V))Γ and p(V) is open normal; this furnishes a finite quotient pullback and a normal partial section.','The profinite topology and continuity are indispensable. In the geometric setting they must be built using finite definition of the pair and its finite automorphisms.','agrees','The note correctly reads the assertion across scans 10–11 and identifies normality as the condition permitting the quotient.')
add([17],'idea of the earlier run',[(11,365,372)],'«ss-groupe invariant … ce qui revient au = … commute à»','Normal image of a partial section implies centralization of the finite kernel, but the converse fails at a fixed open normal subgroup. In D8→D8/⟨r²⟩, the section image ⟨s⟩ centralizes the central kernel, yet r s r⁻¹=r²s∉⟨s⟩. A corrected equivalence also requires invariance under conjugation by the whole extension.','The counterexample is the earlier run’s idea, independently recomputed here. It tests the literal group-theoretic sentence; a geometric realization is not asserted.','agrees','The note accurately identifies an actual overclaim in the source. Shrinking to an open normal subgroup disjoint from H repairs existence but does not prove the fixed-subgroup equivalence.')
add([18],'unproved claim',[(12,378,390),(13,395,416)],'«quitte à passer à une surextension finie assez grande»','Two continuous partial sections with finite kernel defined on open subgroups coincide after restricting to a sufficiently small open subgroup whenever their difference is a continuous finite-valued cocycle; in the centralizer case it is a homomorphism into the finite centre. Geometric models become identified after a finite extension that defines a chosen comparison isomorphism.','Equality of sections and existence of a marked isomorphism are kept separate. The finite-kernel and continuity hypotheses make the asserted eventual equality valid.','agrees','The source allows multiple fixed-field models and asserts eventual agreement; the note properly asks for the finite-definition and restriction argument.')
add([19],'unpursued implication',[(12,388,390),(13,395,416)],'«suite exacte centrale»; «une solution unique»','For finite H⊲E with E/H=Γ, Z=C_E(H) has kernel Z(H) under E→Γ and open image Γ0. Thus 1→Z(H)→Z→Γ0→1 is central. If Z(H)=1, the projection is an isomorphism; a centralizing partial section over Γi exists uniquely iff Γi⊂Γ0.','This states uniqueness of the section satisfying centralization, not uniqueness of every unmarked geometric model.','agrees','Equations (28)–(31) and the centreless conclusion give precisely this centralizer construction and image condition.')
add([20],'unproved claim',[(14,420,422)],'«l’obstruction … H²(Γ_i,z)»; «H¹(Γ_i,z)=Hom(Γ_i,z)»','For a continuous central extension of a profinite group Γi by a finite discrete abelian group z, with trivial Γi-action, the extension class in continuous H² vanishes exactly when a continuous section exists. If nonempty, the set of sections is a torsor under H¹=Hom_cont(Γi,z).','Continuous cochains and the torsor wording are modern explicit formulations; the manuscript names only the two groups.','agrees','The source records trivial action and both degrees. It gives no cocycle construction on this page.')
add([21],'reading question',[(15,441,471),(23,762,768)],'«G=Γ⋉Qbar*»; «z↦1/z»','For G_m over an algebraically closed characteristic-zero field, automorphisms preserving the ordered punctures (0,∞) are t↦at; those preserving the unordered set are t↦at or a/t. Their semilinear group therefore has an extra inversion factor unless the ordering is part of the data.','The missing marking is a reconstruction, not a corrected transcription.','agrees','The displayed group omits inversion, while scan 23 explicitly exhibits it. The note correctly treats the retained marking as the unresolved scope issue.')
add([22,24],'unproved claim',[(16,483,501),(17,505,506)],'«indépendant du choix de s»; «à isom unique près»','For a labelled finite subset S⊂P¹(Qbar), |S|≥3, normalize any ordered triple to (0,1,∞) and let K be the field generated by all remaining coordinates. Fractional-linear change of triple proves independence of K. The labelled pointed curve has a unique K-descent up to the unique isomorphism compatible with its Qbar identification and all labels. Its set-preserving automorphisms are defined over K and inject into Sym(S).','Labelling and compatibility with the specified base-change isomorphism are necessary for unique-isomorphism language; unmarked triples have S3 automorphisms.','agrees','The notes supply the correct marking qualification. A unique abstract unmarked model would overstate the page’s possible meaning.')
add([23],'unproved claim',[(15,428,439)],'«Card S∈{0,1}, alors X′=X»','Over an algebraically closed field of characteristic zero, P¹ and A¹ have trivial étale fundamental group, hence no nontrivial connected abelian finite étale covers. For A¹ in positive characteristic the same conclusion needs the tame/prime-to-characteristic restriction.','The standing k=Q fixes characteristic zero. A topological proof via comparison is reconstructed.','agrees','The source narrows to Q immediately before these base cases; the note preserves that field.')
add([25],'idea of the earlier run',[(19,578,600)],'«g(z)=27z²(z−1)²/[4(z²−z+1)³]»','Over Q, g:P¹→P¹ has degree six, is invariant under z↦1−z and z↦1/z, and is the quotient by the S3 they generate. Its fibres over 0,1,∞ have multiplicity partitions (2,2,2),(2,2,2),(3,3).','The quotient identification and derivative check are an earlier-run elaboration of the displayed function and list; recomputed here.','agrees','The exact function and ramification list are present. The independently checked polynomial identity supports the note’s conclusion.')
add([26],'reading question',[(19,593,600)],'«z²−5/2+1»; «2z²−5+2»','The identity required by g−1 is 4(z²−z+1)³−27z²(z−1)²=(z+1)²(2z−1)²(z−2)². Expanded intermediate factors require −(5/2)z and −5z, and the leading factor sign is +4.','These are mathematical alternatives only; the literal missing-z expressions and uncertain sign remain unchanged.','agrees','Exact symbolic expansion confirms the note’s alarm; it does not determine whether the defect is in the ink or its transcription.')
add([27],'reading question',[(19,563,578),(23,750,760)],'«Q[√[n]{2}]»','The field generated by all roots of X^n−2 is Q(μ_n,2^(1/n)); Q(2^(1/n)) with a single positive root is generally smaller, already for n=3. In a roots-as-a-set convention the source’s notation can mean the splitting field.','No convention is silently chosen. The exact distinction is recorded for arithmetic Galois groups.','agrees','The note correctly distinguishes a chosen radical from the full fibre and retains the source’s ambiguous bracket notation.')
add([28,69,70],'conjecture',[(20,602,615),(20,637,649)],'«image de dim n+1 ?»; «image d’indice fini ???»','For multiplicatively independent algebraic numbers ξ1,…,ξr over a number field K, the compatible radical action lies in Zhat(1)^r⋊χ(G_K). The page asks whether its image has finite index and, in a suitable ℓ-adic interpretation, dimension r+1.','A number field, finite rank r, continuity, and an ℓ-adic meaning of dimension must be specified; the source’s rank glyph and ambient torus are not completely fixed.','agrees','The independence condition and both question marks are explicit. The note rightly does not identify dimension of an adelic profinite group without choosing a meaning.')
add([29,85],'withdrawn in the same text',[(21,653,674),(22,704,724)],'«Hom» [deleted]; «φ(γγ′)=φ(γ)+γφ(γ′)»','For ξ∈K* and θ^n=ξ, σ↦σθ/θ is a continuous μ_n-valued cocycle with its natural cyclotomic action. Replacing θ by uθ changes it by the coboundary σu/u. K*/K*^n≅H¹(G_K,μ_n); Z/n notation must retain the Tate twist.','The source’s μ_n, Z/n and Zhat coefficient variants are disambiguated here for the mathematical statement, not changed in the transcription.','agrees','The deletion of Hom and the surviving cocycle law show an actual correction from homomorphisms to twisted cocycles.')
add([30],'idea of the earlier run',[(21,684,690),(22,713,724)],'«lim Q*/Q*ⁿ»; «Zhat^P»','The n-power completion of Q* is {±1} times the restricted inverse-limit lattice lim_n ⊕_p Z/n. Its valuation image in ∏_p Zhat consists exactly of tuples whose reduction modulo every n has finite support. It is not the unrestricted product.','The support restriction is the earlier run’s elaboration, independently justified here. The completion is the n-power completion, not the full profinite completion over all finite-index subgroups.','agrees','The note correctly supplies both directions and the factorial/all-ones examples; this is necessary to interpret the page’s ambiguous product notation.')
add([31,33,63,71,96],'self-flagged step',[(20,637,649),(23,750,760),(36,1338,1346)],'«d’indice fini ?»; «est-on … surjectif»','For coherent roots θ_n=2^(1/n), the radical extension L=Q(μ∞,2^(1/n):n≥1) gives a closed subgroup G⊂Zhat⋊Zhat* with coordinates σθ_n=ζ_n^b θ_n and σζ_n=ζ_n^a. Its exact image satisfies (−1)^b=(2/a), a quadratic character of conductor 8; hence [Aff:G]=2 and it is not surjective.','The full-index result is supplied by opened literature; the earlier note had independently checked only level eight. The base field Qbar/Qbar alternative is retained as an ink question, with Q as the mathematical hypothesis.','agrees','The notes accurately separate their finite counterexample from the previously unreviewed full-index assertion. This run supplies a verified full-tower theorem and retains the author’s question marks.')
add([32,95],'unpursued implication',[(23,760,768),(40,1482,1509)],'«en choisissant une origine»; «ax+b»; «ax−b»','A coherent radical origin trivializes the torsor K(2), giving affine coordinates x↦ax+b. Under inversion K(2)→K(1/2), transported coordinates give x↦ax−b. Changing the origin conjugates the affine representation by a translation.','Choosing positive real roots is an additional convention of the earlier modernized account and of our computation; it is not a manuscript adjective.','agrees','The page writes the two opposite translation signs and explicitly chooses an origin; the note properly attributes positivity to the modernization.')
add([34,86],'withdrawn in the same text',[(23,750,776)],'«Γ′≃(Z/6nZ)*·μ_ν» [deleted]; «splitting dépend du choix»','The affine automorphism group of a nonempty torsor splits after choosing an origin. This does not imply that its arithmetic image is the entire affine group or that an associated arithmetic extension splits. The provisional finite Γ′ formula is cancelled.','The ambiguous extension labels cannot be converted into an unconditional arithmetic splitting theorem.','agrees','The cancellation and the chosen-root marginal caveat are both present. The note retains the distinction between ambient affine coordinates and the Galois subgroup.')
add([35,84],'idea of the earlier run',[(21,668,688),(22,709,724)],'«H¹»; «Z¹»; «éléments d’ordre 2» [deleted]','For the natural G_Q-module μ_n, 0→μ_n/μ_n(Q)→Z¹(G_Q,μ_n)→H¹(G_Q,μ_n)→0 is exact. At n=2 the first term is zero, so an extra Z/2 kernel over this fixed quotient is false.','The exact sequence is the reconstruction; the cancelled denominator does not state a finished replacement. Abstract isomorphisms of infinite groups are irrelevant to the comparison over the fixed quotient.','agrees','The note’s modulus-two counterexample tests the actual extension maps, and the source leaves its attempted invariant denominator unfinished.')
add([36,58],'unpursued implication',[(25,789,830),(44,1682,1689)],'«2n² triangles»; «g_n=(n−1)(n−2)/2»','For C_n→C_1 over Q, degree n² and three fibres of n points each of ramification index n yield g(C_n)=(n−1)(n−2)/2. The lifted two-triangle sphere has V=3n, E=3n², F=2n². Genera at n=1,2,3,4,6,12 are 0,0,1,3,10,55.','The Riemann–Hurwitz and Euler-characteristic derivations fill in the manuscript’s arithmetic.','agrees','Both counts and genus values agree with the manuscript and the independently redone computations.')
add([37,89],'withdrawn in the same text',[(26,833,872),(27,896,914),(28,924,937)],'«C_n′→C_n … n′=nd»; «rev. principal»','For n′=nd, the transition C_n′→C_n sends [X:Y:Z] to [X^d:Y^d:Z^d], and μ_n′³/μ_n′→μ_n³/μ_n is induced by d-th powers. Over U the inverse system is a pro-étale torsor under T³/T.','The coordinate arrow in the diplomatic display appears reversed; the equation-preserving direction is given here as a mathematical reconstruction. Projective inverse limits are treated as pro-objects when needed.','agrees','The notes preserve the finite-first revision and the actual compatible power maps; the literal display’s arrow issue remains in the readings index.')
add([38],'unproved claim',[(27,875,914),(28,917,937),(39,1434,1443)],'«On voit tout de suite»; «par homothéties»','S3 acts on M_n=μ_n³/μ_n by coordinate permutations; G_Q acts through χ_n on μ_n. The actions commute, preserve the diagonal, and commute with all power transitions, giving (S3×G_Q)⋉M_n and its inverse-limit action.','The action convention is stated explicitly; the semidirect notation is not a direct-product assertion.','agrees','All component actions and the scalar character occur in the cited formulas; the note accurately supplies the elementary compatibility check.')
add([39],'reading question',[(28,938,948)],'«Aut_Q(C_1)»; «…⋉μ_n»','For the marked covering of the three-punctured line, the relevant semilinear automorphisms are (S3×G_Q)⋉π_n, with π_n=μ_n³/μ_n. The bare unmarked formula is false already for C_1=P¹, whose automorphisms include t↦t+2. The written μ_n has rank one whereas the deck group has rank two.','Marked-cover scope and π_n in place of μ_n are proposed mathematical readings only. No classification of all Fermat-curve automorphisms is imported.','agrees','The note correctly identifies both the missing marking and the group-size discrepancy in the literal formula.')
add([40],'unproved claim',[(28,951,960),(29,963,971)],'«π₁(Cbar_1*)ab→π∞» [isomorphism]','For U=P¹_Qbar−{0,1,∞}, the tower C_n* realizes the maximal abelian profinite geometric cover: π₁(U)ab≅Zhat(1)³/diag Zhat(1). Peripheral generators map to the coordinate classes with their sole sum-zero relation.','Comparison with the three-punctured complex sphere and its geometric base-change invariance is the reconstructed proof.','agrees','Equation (14) explicitly abelianizes; the note correctly avoids identifying the full free profinite group with this rank-two module.')
add([41],'unpursued implication',[(29,973,998)],'«image inverse de −1∈μ_2»','The fibre of C_n over x=0 is the n-element torsor {λ:λ^n=−1}, using λ=y/z; similarly for the other coordinate-zero fibres. Its inverse limit is K(−1), with inertia line the image of the corresponding T-factor in T³/T.','Projective triples must be quotiented by all nonzero scalar multiples before taking the ratio; the written /μ_n in the preliminary ambient description is not literally sufficient.','agrees','The ratio and inverse-limit torsor agree with the note. This run additionally flags the ambient projective quotient in the same display.')
add([42,87],'withdrawn in the same text',[(29,994,1000),(30,1018,1053)],'«E_i≃p⁻¹({i})/Z_i»','Put M=T³/T, p:M→M/2M, and let Zi be the coordinate inertia line. On p⁻¹(i), the deck action is m:y↦y+2m. Therefore E_i≅p⁻¹(i)/(2Zi), using ordinary translations in the quotient, or equivalently quotient by Zi acting through doubling. Its stabilizer as an M-set is Zi.','The action-through-doubling convention makes the written Zi denominator coherent; ordinary Zi translation does not preserve the coset.','agrees','The displayed multiplication-by-two sequence supplies the required action. The note is careful not to turn the denominator into an unconditional ink error.')
add([43],'unpursued implication',[(30,1008,1016),(30,1044,1048)],'«π_2* … I={0,1,∞}»','The three nonzero elements of M/2M≅F₂² are the three coordinate inertia classes, equivariantly for S3≅GL₂(F₂). G_Q acts trivially at this modulus.','The marginal claim about three rational points on Cbar_∞ or Cbar_2 is not used: C_2:x²+y²+z²=0 has no Q-point.','agrees','The main mod-two statement is correct. The note correctly declines to identify the doubtful marginal curve, and this run records the arithmetic obstruction to either literal rational-point reading.')
add([44,88,93],'withdrawn in the same text',[(31,1059,1105),(32,1115,1153),(33,1157,1192),(34,1195,1203)],'«Isom(I,μ_3)»; «le quotient … a donc deux éléments»','For char 0, the six bijections I→μ_3 modulo diagonal μ_3 give the two S3/A3-fixed points α=−jbar and αbar=−j of C_1. At level n the relevant cone is {(x,y,z)∈μ_3n³:(x^n,y^n,z^n) is a bijection I→μ_3}; quotienting by μ_3n gives the 2n² points over this pair.','This is the coherent surviving construction. The uncertain 2n/3n, 2n/n, μ_n/μ_3 and bar/tilde glyphs remain unaltered; deleted earlier cone/cubing attempts are recorded.','agrees','The six-bijection count and quotient agree; the note correctly treats the inconsistent exponents and group labels as scan questions.')
add([45],'idea of the earlier run',[(34,1218,1226)],'«une droite invariante … elle est unique»','On F₃³/diag F₃, a 3-cycle has matrix [[0,−1],[1,−1]]. Its unique invariant line is span(1,−1); its two nonzero vectors form ω. A transposition acts on the line by −1, and the joint S3×G_Q character is sgn·χ_3.','The explicit matrix and sign character are the earlier run’s computation, redone independently.','agrees','The source asserts uniqueness of the line and identifies its nonzero pair; matrix calculation proves exactly that assertion.')
add([46],'reading question',[(34,1204,1216)],'«π∞ —3→ π∞ —p_3→ π_3»','The M-action on p_3⁻¹(ω) is m:y↦y+3m; each of the two residue cosets is a free M-torsor. Ordinary unscaled translation would not preserve the set.','The action is read from the displayed exact sequence; no missing action prescription is alleged.','agrees','The note correctly emphasizes that the manuscript itself supplies the multiplication-by-three arrow.')
add([47],'unpursued implication',[(35,1230,1295)],'«K(−1/2)≃K(−1)∧_T K(2)⁻¹»','Over Qbar in characteristic zero, the midpoint fibre above α′(i) is K_n(−1/2)^(I minus {i}); its inverse limit is the corresponding product of T-torsors. Multiplication of roots induces K(a)∧_T K(b)≅K(ab), giving the stated identity.','The parameters must be nonzero. Formula (35)’s apparent quantifier over all Qbar requires excluding 0 for a torsor.','agrees','The note correctly describes the contracted product and S3-permuted midpoint fibres. This run additionally states the nonzero parameter needed by the torsor assertion.')
add([48],'unpursued implication',[(36,1300,1346),(37,1350,1360)],'«les opérations … se font à travers»','Let A=Aff(T,K(1/2)). The listed deck, branch, centre and midpoint actions factor through (S3×A)⋉M; A acts on M through its linear character, and its translation part affects the midpoint torsor.','This is a factorization of the listed finite/tower-set actions, not an identification of the full arithmetic outer automorphism group.','agrees','Both the ambient affine group and the homomorphism from the arithmetic group are displayed; the note retains the precise limited target.')
add([49,83],'withdrawn in the same text',[(15,424,437),(37,1362,1372)],'«n’importe quel corps premier … n premiers à la car.»','The Fermat covers and maximal tame abelian tower generalize to an algebraically closed field of characteristic p using n prime to p. The entire preceding special-fibre package does not generalize unchanged in p=2 or 3: −1/2 is undefined at p=2 and μ_3 ceases to be three distinct points at p=3.','The core covering claim is separated from the literal broader words “les développements précédents.” Auxiliary eight-point and affine-torsor formulas require char≠2,3; their number-field finite-index conclusion is separate.','understates','The earlier note correctly retained the prime-to-n restriction but did not identify that it is insufficient for all preceding auxiliary constructions.',{49:('corrected','Added the characteristic-2/3 exclusions for the special fibres and separated arithmetic finite-index claims from geometric tame covering theory.'),83:('merged into item SA09-153','Retained the earlier deletion of the prime-field setup and its later qualified return.')})
add([50],'idea of the earlier run',[(25,826,830),(29,963,971),(44,1682,1689)],'«il est 1 ssi n=3»','For the degree-nine punctured Fermat cubic, H=ker(Fhat₂→(Z/3)²) is free profinite of rank 10. Filling its nine punctures quotients by their closed normal inertia closure, giving π₁(C_3), whose abelianization is the proper elliptic Tate module of rank two.','The cover-and-filling map is the earlier run’s construction, not an assertion written on these pages. The rank-two base deck quotient and the proper elliptic Tate module are different Galois representations.','agrees','The note labels the deduction as its own and gives the correct puncture count and maps; no manuscript CM theorem is inferred.')
add([51],'idea of the earlier run',[(31,1059,1081),(34,1218,1226),(40,1482,1509)],'«en choisissant une origine»','The mod-two/mod-three reductions, sign character and radical origins can be compared with the named external CM-parity research runs only after specifying their frame maps.','All statuses of LM7_PUSH D.50/E.58/E.62/E.64/E.65/E.3 and EXIT_TOWER E.49 are attributed reports from the unavailable context digest.','not on the page','The manuscript contains the small-modulus data, but no identification with the project’s Δ-character or resolution of its status discrepancy. The note is retained exclusively as a project lead.')
add([52,94],'reading question',[(37,1368,1372),(39,1458,1477)],'«ρ_0ρ_1ρ_∞=1»; «Ce sont ces éléments qui donnent l’isom»','The coordinate classes ρ_i in Zhat³/diag Zhat satisfy ρ_0+ρ_1+ρ_∞=0. They realize the peripheral abelianization of the oriented three-punctured-sphere/cartographic group. The precise handwritten source-group subscript is uncertain.','The abelian quotient is fixed by equation (14); an isomorphism from the full nonabelian cartographic group is excluded.','agrees','The note correctly isolates the doubtful subscript while retaining the clear abelian target and peripheral relation.')
add([53],'idea of the earlier run',[(38,1397,1427)],'«ζ_n=exp(2iπ/3n)»; «la base canonique»','The exponential system ζ_n lies in lim_n μ_3n, not componentwise in μ_n. Cofinal reindexing identifies this limit with T=lim_n μ_n by (v_n)↦(v_n³), inverse (u_n)↦(u_3n). Under this isomorphism it gives the usual complex exponential generator of T.','The cofinal interpretation is the earlier run’s explicit reconstruction; “canonical” is relative to the chosen complex embedding/exponential orientation.','agrees','The note supplies actual inverse maps and does not silently replace 3n by n in the source.')
add([54,92],'reading question',[(31,1059,1081),(38,1383,1420),(39,1450,1456)],'«α=−jbar»; «(−1,+1,0)»','With t=−x^n/z^n and α_n=(ζbar_n,ζ_n,1), the chosen point lies over α=−jbar. Complex conjugation exchanges it with αbar=−j and sends the coordinate vector to its negative.','Hua’s alternative naming −j is a convention of the earlier account; no source renaming is made.','agrees','Direct nth-power substitution confirms the source’s chosen member of the pair; the note correctly records rather than suppresses the naming difference.')
add([55,72],'self-flagged step',[(40,1514,1534),(41,1538,1557)],'«ces 18 flèches … deux d’entre elles»','The manuscript proposes parallel transports among centre, midpoint and branch fibres, with equivariance under M and S3×{1,complex conjugation}, and says two representative arrows determine the eighteen displayed maps. A chosen path system and compatibility with stabilizers/composites are still required.','No arbitrary G_Q-equivariance is supplied: Γ is deleted in favour of the complex-conjugation subgroup. The packet stops after one coordinate construction.','agrees','The question mark and unfinished reduction are real manuscript flags. The note correctly distinguishes a symmetry reduction from a completed transport construction.')
add([56],'idea of the earlier run',[(38,1399,1405),(40,1484,1485),(41,1559,1572)],'«exp(±π i/n)»; «=(θ_n⁻¹ ζbar_n,θ_n⁻¹ ζ_n,1)»','The first displayed midpoint triple has nth powers (−1/2,−1/2,1), summing to 0. Using the earlier ζ_n=exp(2πi/3n), the equalized second triple has nth-power sum 1/2 and is not on C_n. The limit formula also replaces θ_n⁻¹ by θ∞.','Possible repair: distinguish η_n=exp(πi/n) from ζ_n and retain inverse θ; no such emendation is made.','agrees','The note’s exact substitution detects two independent incompatibilities. This run recomputes the residuals and sends both to the scan-reading index.')
add([57],'unpursued implication',[(42,1578,1623)],'«I∈Ob Ens_3»; «Or(I)»','For a three-element set I, M(I)=Zhat^I/diag Zhat is functorial under bijections. Its mod-three A3-fixed nonzero pair is an orientation torsor with sign action; its intrinsic arithmetic form includes the χ_3 twist.','An identification with the bare orientation torsor uses a chosen complex cube root. The final deleted arrow label does not specify a completed transport map.','agrees','The object formulas are present and functorial. The note correctly attributes any completion of the final arrow to modernization.')
add([59,73],'self-flagged step',[(44,1693,1718)],'«Sauf erreur, c’est l’octaèdre»; «d’ordre 24»','The triangulation of the complex conic C_2 has six vertices, twelve edges and eight faces, with graph K_2,2,2. Its oriented unlabelled triangular-map automorphism group is V₄⋊S₃≅S₄ of order 24; preserving all three colours restricts to V₄.','The qualification “unlabelled” is explicit in the modern statement because allowing permutation of types yields S3. The proper conic’s unrestricted algebraic automorphism group is larger.','agrees','The source’s qualified identification and order are correct for the stated map structure, as verified by the finite permutation action.')
add([60,91],'withdrawn in the same text',[(44,1714,1733)],'«les trois s-groupes F₂»; «dièdre» [deleted], «monoèdre» [inserted]','The three lines L⊂V₄ give three degree-two intermediate covers C_2/L→C_1, permuted by S3. Their branch pairs are the three two-element subsets of {0,1,∞}.','The covering statement is definite; monoèdre/bièdre/dièdre nomenclature is not standardized by altering the source.','agrees','The quotient subgroup construction is valid. The note accurately preserves the author’s local word substitution and the different word in the margin.')
add([61],'reading question',[(44,1720,1745)],'«subdivision barycentrique du bi-èdre»','The clipped margin relates the octahedron to a subdivision of a bihedron and starts an incomplete universal-cover sentence. The complete mathematical statement is not recoverable from the supplied text.','For the standard regular CW bihedron with two vertices, two edges and two digon faces, the incidence poset gives barycentric graph K_2,2,2 and eight triangles; this exact convention is independently checked here. The clipped universal-cover clause remains unreconstructed.','agrees','The note correctly refuses to complete the clipped words. The subdivision convention is a substantive source question; no finished universal-cover theorem is assigned.')
add([62,77],'title, date or page count',[(18,510,521),(44,1693,1718)],'«Tour des rev. de Fermat C_n»; «revêtements … diédraux»','The title sheet lists Fermat, abelian octahedral and dihedral/paradihedral towers. Scans 25–44 implement the Fermat tower through its n=2 octahedron; the dihedral construction continues in the next supplied package.','The final adjective remains uncertain, and this heading supplies neither a date nor an authorial page count.','agrees','The programme is accurately reported. The continuation must be checked against scans 46–47 in the adjoining package, not merely against Hua’s context account.')
add([64],'idea of the earlier run',[(28,924,937),(39,1434,1443)],'«par homothéties par χ»','Every Zhat-linear automorphism of M commutes with the scalar cyclotomic action; hence its linear centralizer is GL₂(Zhat). This quotient-level calculation does not determine the centralizer of the full outer action on Fhat₂.','The linear-centralizer observation and proposed project application belong to the earlier run.','agrees','The scalar action is explicit. The note correctly retains the missing lift/comparison map to the project’s larger group.')
add([65],'idea of the earlier run',[(27,896,914),(44,1700,1703)],'«…⋉π_n»; «d’ordre 24»','The package offers finite deck representations and the level-two S4 action. It supplies no comparison morphism to the cited level-5,7,11 congruence kernels or nonsolvable completion-centralizer problems.','LM4_SUCCESSOR B.38 and LM4 F.7/C.12 are external research leads only.','not on the page','The note does not claim a solution; it correctly states the missing maps. Its project statuses cannot be verified from the supplied archive.')
add([66],'other',[(37,1368,1372),(42,1578,1623)],'«faire le lien … groupe cartographique»','The note points forward to later same-cote Galois-action and moduli leaves, and externally to cote145. These are continuation leads requiring their own source passages.','Only the present transition is independently read here; root consolidation checks the supplied later138 passages. Cote145/intake materials are absent.','agrees','The note carefully labels later images and intake claims as unaudited context. It does not invent a statement or date on scans1–45.')
add([67],'unpursued implication',[(29,963,971),(44,1682,1689)],'«π₁(Cbar_1*)ab»; «il est 1 ssi n=3»','Ihara’s later Fermat-Jacobian/Tate-module work is a natural comparison to the cover-and-filling construction at n=3. The arithmetic action on the base’s rank-two abelian deck module is not itself the proper Fermat Jacobian representation.','The note verified Ihara’s bibliography only; this run checks the relevant opened source separately and credits the original lead to Hua.','agrees','The manuscript’s objects are present, but no direct technical identification with Ihara follows merely from matching the word Fermat.')
add([68,97],'self-flagged step',[(9,323,339)],'«oubli à réparer ds rédaction au propre!» [words uncertain]','An editorial repair flag is attached to the restricted-field automorphism formulas (23). Its precise omitted content is not specified.','The competing external wording “à vérifier dans les formules” is not substituted for the supplied reading.','agrees','Both notes preserve the actual repair reading and distinguish it from Hua’s alternative. There is no identifiable mathematical conjecture beyond completing this formula block.')
add([74],'title, date or page count',[(1,1,18)],'«IMAG … INSTITUT MONTPELLIERAIN … ALEXANDER GROTHENDIECK»','Scan1 is an institutional cover, with no mathematical title, manuscript date or authorial page count in its transcription.','No inference about authorship of the cover or the mathematics is made.','agrees','The cover was read in full; its logo lettering is administrative metadata.')
add([76],'title, date or page count',[(4,132,137)],'«dictionnaire galoisien / de descente etc…» [all words uncertain]','The tentative heading precedes the numbered descent dictionary; no date or page count is written.','The modern title “Dictionnaire galoisien des descentes” is a contextual editorial title, not a secure exact quotation.','agrees','The note accurately preserves the uncertainty of every title word.')
add([79],'title, date or page count',[(1,1,18),(4,132,137),(18,510,521),(45,1798,1801)],'No authorial page-total sentence.','The combined file contains44 scan markers for positions1–45, omitting24. There is no mspage marker; comment foliation is archival. The catalogue132-page total concerns the whole cote, not this package.','Marker counts describe the supplied transcription, not a new claim about the unseen scans’ physical extent.','agrees','The package count and absence of authorial page numbering can be checked mechanically after the page-by-page read; neither is promoted to manuscript mathematics.')
add([90,100],'withdrawn in the same text',[(35,1232,1259),(38,1403,1414),(40,1511,1512)],'«β» [deleted] → «α′»; «α′(2)»','The source relabels the midpoints with α′, reverses the chosen order of conjugate roots in the basepoint, and retains a later β-shaped residue. The third midpoint index 2 conflicts with the established label set I={0,1,∞}; its coordinate is1/2.','The suggested index∞ and unified labels are editorial alternatives only; actual coordinate changes must be tracked independently of names.','agrees','The note correctly records both revisions and surviving residues rather than standardizing them silently.')
add([99],'reading question',[(19,526,551),(35,1230,1235)],'«0,1,∞,−j,−jbar»; «1/2,2,−1»','In characteristic zero the listed special-point set has eight distinct points: six real points0,1,∞,−1,1/2,2 and two roots of z²−z+1.','The discrepancy with Hua’s reported “sept points” is an external-context report; the count eight is independently confirmed from the supplied formulas.','agrees','The note’s numerical correction follows directly from the displayed sets and discriminant−3.')
add([101],'other',[(4,132,137),(18,510,521),(25,788,830),(42,1576,1624)],'No corresponding manuscript statement.','The indexed entry is an editorial concordance between Hua subsection labels and archive foliation/scan positions. Its local source-side topics agree with the transcription.','Hua’s file is not supplied, so its headings and correspondence beyond this package remain attributed metadata, not checked results.','not on the page','Retained because it is a row of NOTES_INDEX; it is not a Grothendieck claim and has no mathematical proof status.')
add([102],'other',[],'No corresponding manuscript statement.','The indexed entry inventories prior-project result identifiers, statuses, filenames and claimed referee limits through an unavailable RESULTS_STATE digest.','All project statuses are quoted only as reports of the earlier run; none receives a new mathematical validation event.','not on the page','Retained as provenance metadata because it is indexed. The absence of those project documents prevents checking their theorem statements or referee claims.')

def write_tsv(name,rows,fields):
    with (W/name).open('w') as f:
        wr=csv.DictWriter(f,fieldnames=fields,delimiter='\t',lineterminator='\n');wr.writeheader();wr.writerows(rows)
assert len(entries)==102
assert sorted(int(e['entry_id'].split('#')[1]) for e in entries)==list(range(1,103))
assert len({i['id'] for i in items})==len(items)
(W/'items.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
write_tsv('entries.tsv',sorted(entries,key=lambda e:int(e['entry_id'].split('#')[1])),['entry_id','item_id','verdict','reason'])
write_tsv('CHECK_EVENTS.tsv',events,['statement_id','date','who','type','outcome'])
with (W/'progress.log').open('a') as f:f.write(datetime.datetime.now(datetime.timezone.utc).isoformat()+f' STAGE1: model read all102 notes, all44 scan passages and complete605-line doubt table; wrote{len(items)} semantic items and102 verdicts.\n')
print(json.dumps({'entries':len(entries),'items':len(items),'source_coverage':'1–102 exactly once'},ensure_ascii=False))
